from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/")
async def root(my_header: str = Header(convert_underscores=False)):
    return {"my_header": my_header}

client = TestClient(app)

def test_convert_underscores_false():
    # Should accept my_header when convert_underscores=False
    response = client.get("/", headers={"my_header": "hello"})
    print(f"my_header: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"my_header": "hello"}

def test_convert_underscores_true():
    # Should NOT accept my_header when convert_underscores=True
    # We need a separate app for this or a different endpoint
    pass

if __name__ == "__main__":
    test_convert_underscores_false()
    print("test_convert_underscores_false passed!")
